import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CAzL99r7.js";const m=JSON.parse('{"title":"Privacy Policy & Data Governance","description":"","frontmatter":{},"headers":[],"relativePath":"privacy/index.md","filePath":"privacy/index.md"}'),r={name:"privacy/index.md"};function n(s,e,l,c,d,g){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="privacy-policy-data-governance" tabindex="-1">Privacy Policy &amp; Data Governance <a class="header-anchor" href="#privacy-policy-data-governance" aria-label="Permalink to &quot;Privacy Policy &amp; Data Governance&quot;">​</a></h1><p><strong>Effective Date:</strong> November 2026 | <strong>SDK Version:</strong> 2.2.2</p><p>The <strong>Veg Sahayyak SDK</strong> is built on a strict <strong>Privacy-First Telemetry Architecture</strong>. We believe commercial fleets, logistics providers, enterprise developers, and motorists deserve high-precision speed compliance and road safety intelligence without compromising location privacy or exposing drivers to pervasive tracking.</p><hr><div class="tip custom-block"><p class="custom-block-title">Privacy-First Telemetry Guarantee</p><p>Core speed tracking operates <strong>100% offline on-device</strong>. For tiered commercial licenses, a lightweight periodic heartbeat transmits session duration and total distance traveled for billing reconciliation. <strong>Zero GPS coordinates, routes, or location points are ever logged, cached, or transmitted to any remote server or third-party cloud.</strong></p></div><hr><h2 id="_1-information-access-processing-scope" tabindex="-1">1. Information Access &amp; Processing Scope <a class="header-anchor" href="#_1-information-access-processing-scope" aria-label="Permalink to &quot;1. Information Access &amp; Processing Scope&quot;">​</a></h2><h3 id="a-location-sensor-access-access-fine-location-access-coarse-location" tabindex="-1">A. Location Sensor Access (<code>ACCESS_FINE_LOCATION</code>, <code>ACCESS_COARSE_LOCATION</code>) <a class="header-anchor" href="#a-location-sensor-access-access-fine-location-access-coarse-location" aria-label="Permalink to &quot;A. Location Sensor Access (`ACCESS_FINE_LOCATION`, `ACCESS_COARSE_LOCATION`)&quot;">​</a></h3><ul><li><strong>Purpose:</strong> Device location data is accessed solely in real time while the vehicle is in motion to calculate velocity, apply Exponential Moving Average (EMA) jitter smoothing, and evaluate profile speed alerts (such as over-speed and minimum speed corridor warnings).</li><li><strong>Processing:</strong> <strong>100% on-device</strong> within secure native execution memory.</li><li><strong>Ephemeral Retention:</strong> GPS data points are processed ephemerally in RAM and immediately discarded. Latitude, longitude, altitude, heading, and geographic routes are <strong>never</strong> written to persistent disk storage, cached in local databases, or transmitted externally.</li></ul><h3 id="b-enterprise-telemetry-tiered-billing-reconciliation" tabindex="-1">B. Enterprise Telemetry &amp; Tiered Billing Reconciliation <a class="header-anchor" href="#b-enterprise-telemetry-tiered-billing-reconciliation" aria-label="Permalink to &quot;B. Enterprise Telemetry &amp; Tiered Billing Reconciliation&quot;">​</a></h3><p>To reconcile commercial license quotas without compromising privacy, the SDK provides two operating tiers:</p><ul><li><strong>Tiered Commercial Licenses:</strong> Emits an aggregated periodic session heartbeat (<code>TelemetryJobService</code>) containing strictly non-locational accounting metrics: <ul><li><code>client_id</code>: Organization license identifier</li><li><code>start_time</code> &amp; <code>end_time</code>: Session start and end timestamps</li><li><code>duration_ms</code>: Total driving duration in milliseconds</li><li><code>distance_meters</code>: Cumulative distance traveled in meters</li><li><em>(Trivial movements under 100 meters or under 10 seconds are automatically filtered out and never recorded.)</em></li></ul></li><li><strong>Unlimited Commercial Licenses:</strong> Enterprise clients with an unlimited license tier <strong>completely bypass the telemetry engine at the native layer</strong>. In this tier, zero HTTP network connections are initiated and all processing remains strictly on-device.</li></ul><hr><h2 id="_2-data-protection-sharing-safeguards" tabindex="-1">2. Data Protection &amp; Sharing Safeguards <a class="header-anchor" href="#_2-data-protection-sharing-safeguards" aria-label="Permalink to &quot;2. Data Protection &amp; Sharing Safeguards&quot;">​</a></h2><ul><li><strong>Zero Location Data Transmission:</strong> Under no circumstances are GPS fixes, coordinates, or driving routes transmitted to any remote server or third-party cloud.</li><li><strong>Zero Data Brokerage:</strong> We do not sell, rent, monetize, or trade any data processed by the SDK to advertising networks, data brokers, or commercial aggregators.</li><li><strong>No Ad-Trackers or Profiling:</strong> The SDK contains zero advertising identifiers, tracking pixels, or behavioral profiling tools.</li></ul><hr><h2 id="_3-developer-guidance-google-play-data-safety" tabindex="-1">3. Developer Guidance: Google Play Data Safety <a class="header-anchor" href="#_3-developer-guidance-google-play-data-safety" aria-label="Permalink to &quot;3. Developer Guidance: Google Play Data Safety&quot;">​</a></h2><p>If you publish an Android application integrating the Veg Sahayyak SDK on the <strong>Google Play Store</strong>, use the following guidance to complete your <strong>Google Play Data Safety Form</strong>:</p><h3 id="understanding-ephemeral-processing" tabindex="-1">Understanding Ephemeral Processing <a class="header-anchor" href="#understanding-ephemeral-processing" aria-label="Permalink to &quot;Understanding Ephemeral Processing&quot;">​</a></h3><p>Under Google Play Developer Policy, data processed strictly locally on-device in real time and not saved to persistent storage or sent off the device is categorized as <strong>Ephemeral Processing</strong>. Ephemeral data is <strong>not classified as &quot;Collected&quot;</strong> under Google Play Data Safety rules.</p><h3 id="play-console-declarations-for-the-sdk" tabindex="-1">Play Console Declarations for the SDK <a class="header-anchor" href="#play-console-declarations-for-the-sdk" aria-label="Permalink to &quot;Play Console Declarations for the SDK&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Data Category</th><th style="text-align:left;">Handled by SDK</th><th style="text-align:left;">Classified as &quot;Collected&quot;?</th><th style="text-align:left;">Shared Externally?</th><th style="text-align:left;">Developer Declaration Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Precise Location</strong></td><td style="text-align:left;">Ephemeral (RAM only)</td><td style="text-align:left;"><strong>No</strong></td><td style="text-align:left;"><strong>No</strong></td><td style="text-align:left;">Used strictly on-device for real-time speed calculation. Not collected.</td></tr><tr><td style="text-align:left;"><strong>Approximate Location</strong></td><td style="text-align:left;">Ephemeral (RAM only)</td><td style="text-align:left;"><strong>No</strong></td><td style="text-align:left;"><strong>No</strong></td><td style="text-align:left;">Used strictly on-device for real-time speed calculation. Not collected.</td></tr><tr><td style="text-align:left;"><strong>Personal &amp; Device IDs</strong></td><td style="text-align:left;">None</td><td style="text-align:left;"><strong>No</strong></td><td style="text-align:left;"><strong>No</strong></td><td style="text-align:left;">The SDK does not access IMEI, Android ID, MAC address, or user accounts.</td></tr><tr><td style="text-align:left;"><strong>Session Metrics</strong></td><td style="text-align:left;">Aggregate Only</td><td style="text-align:left;"><strong>Optional</strong> <em>(Tiered only)</em></td><td style="text-align:left;"><strong>No</strong></td><td style="text-align:left;">Total distance and duration only for B2B billing reconciliation.</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>If your host application does not independently store or transmit location coordinates elsewhere in your codebase, you can declare in the Google Play Console that your app does not collect or share location data.</p></div><hr><h2 id="_4-legal-regulatory-frameworks" tabindex="-1">4. Legal &amp; Regulatory Frameworks <a class="header-anchor" href="#_4-legal-regulatory-frameworks" aria-label="Permalink to &quot;4. Legal &amp; Regulatory Frameworks&quot;">​</a></h2><p>The Veg Sahayyak SDK&#39;s architecture is designed to comply with global privacy standards by design:</p><ul><li><strong>Google Play User Data &amp; Location Policy:</strong> Fully satisfies Google Play&#39;s Background Location, Foreground Service Location (<code>FOREGROUND_SERVICE_TYPE_LOCATION</code>), and Prominent Disclosure requirements through on-device computation and transparent data practices.</li><li><strong>GDPR (General Data Protection Regulation):</strong> Complies with the core principles of Data Minimization (Article 5(1)(c)), Purpose Limitation, and Storage Limitation.</li><li><strong>India DPDP (Digital Personal Data Protection Act):</strong> Local on-device execution ensures that sensitive personal location data is never transferred outside user control.</li><li><strong>California CCPA / CPRA:</strong> The SDK does not &quot;sell&quot; or &quot;share&quot; consumer personal information as defined by California privacy statutes.</li><li><strong>ESG &amp; Fleet Transport Governance:</strong> Enables enterprise sustainability initiatives (Scope 1 fleet emissions reduction via speed regulation) without introducing privacy compliance risks.</li></ul><hr><h2 id="_5-contact-compliance-inquiries" tabindex="-1">5. Contact &amp; Compliance Inquiries <a class="header-anchor" href="#_5-contact-compliance-inquiries" aria-label="Permalink to &quot;5. Contact &amp; Compliance Inquiries&quot;">​</a></h2><p>If you or your legal, compliance, or security teams have questions regarding our Privacy Policy or require custom Data Processing Agreements (DPA), please contact us:</p><div class="interactive-card" style="margin-top:16px;padding:20px;border-radius:12px;background:var(--vp-c-bg-soft);border:1px solid var(--vp-c-divider);"><p style="margin:0 0 12px 0;"><strong>Veg Sahayyak Telematics Engineering &amp; Compliance</strong></p><ul style="list-style:none;padding-left:0;margin:0;display:flex;flex-direction:column;gap:8px;"><li>📧 <strong>Email:</strong> <a href="mailto:vegsahayyak@gmail.com">vegsahayyak@gmail.com</a></li><li>🏢 <strong>Enterprise Licensing:</strong> <a href="/contact/">Commercial Inquiries &amp; Contact Form</a></li><li>💼 <strong>LinkedIn:</strong> <a href="https://www.linkedin.com/company/veg-sahayyak" target="_blank" rel="noopener">Veg Sahayyak Company Page</a></li></ul></div>',31)])])}const h=t(r,[["render",n]]);export{m as __pageData,h as default};
